INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(22001, 'Malachi 2:13', 'Malachi', 2, 13, '&nbsp;يو بل کار تاسو وکړئ، تاسو د مالِک خُدائ قربان‌ګاه په اوښکو ډکه کړئ. تاسو وژاړئ او زارى وکړئ ځکه چې نور هغه نۀ ستاسو نذرانو ته ګورى او نۀ يې ستاسو د لاسونو نۀ په خوشحالۍ سره قبلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22002, 'Malachi 2:14', 'Malachi', 2, 14, '&nbsp;تاسو تپوس کوئ چې، ”ولې؟“ دا ځکه چې مالِک خُدائ ستا او ستا د ځوانۍ د ښځې په مينځ کښې ګواه دے، ځکه چې تا د هغې سره ټګى وکړه، اګر کۀ هغه ستا په ژوند کښې شريکه ده، او تا هغې سره نِکاح کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22003, 'Malachi 2:15', 'Malachi', 2, 15, '&nbsp;آيا مالِک خُدائ تاسو دواړه يو نۀ کړئ؟ تاسو په زړۀ او ځان د هغۀ يئ. او خُدائ د دې نه څۀ غواړى؟ ځکه چې هغه نېک اولاد غواړى. نو د خپل زړۀ خيال ساته، او خپلې د ځوانۍ د ښځې سره ټګى مۀ کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22004, 'Malachi 2:16', 'Malachi', 2, 16, '&nbsp;”زۀ طلاق نه نفرت کوم،“ د بنى اِسرائيلو مالِک خُدائ فرمائى، ”او زۀ د هغه سړى نه نفرت کوم چا چې د ظلم جامې اغوستې وى،“ مالِک خُدائ ربُ الافواج فرمائى. ”نو د خپل زړۀ خيال ساتئ، او ټګى مۀ کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22005, 'Malachi 2:17', 'Malachi', 2, 17, '&nbsp;تاسو مالِک خُدائ په خپلو خبرو ستړے کړو. ”مونږ هغه څنګه ستړے کړو؟“ تاسو تپوس کوئ. په دې وئيلو سره چې، ”ټول بد کوونکى د مالِک خُدائ په نظر کښې ښۀ دى او هغه د هغوئ نه رضا دے،“ يا ”اِنصاف کوونکے خُدائ پاک چرته دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22006, 'Malachi 3:1', 'Malachi', 3, 1, '&nbsp;”ګوره، زۀ خپل پېغمبر ستا نه وړاندې لېږم چې ستا مخې ته لاره تياره کړى. بيا به ناڅاپه هغه مالِک چې تاسو يې لټون کوئ خپل کور ته راشى، هغه د لوظ پېغام راوړونکے به راشى د چا چې تاسو ليواله يئ،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22007, 'Malachi 3:2', 'Malachi', 3, 2, '&nbsp;خو د هغۀ د راتلو ورځ څوک برداشت کولے شى؟ څوک ودرېدلے شى کله چې هغه راښکاره شى؟ ځکه چې هغه به لکه د صفا کوونکى اور يا د دهوبى د صابون په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22008, 'Malachi 3:3', 'Malachi', 3, 3, '&nbsp;هغه به لکه د سپينو زرو د صفا کوونکى او خالص کوونکى په شان کښېنى، هغه به ليويان صفا کړى او د سرو او سپينو زرو په شان به يې چاڼ کړى. بيا به دوئ صادقان شى چې مالِک خُدائ ته به نذرانې پېش کولے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22009, 'Malachi 3:4', 'Malachi', 3, 4, '&nbsp;او د يهوداه او يروشلم نذرانې به مالِک خُدائ ته د قبلولو وى، داسې لکه چې په تېرو ورځو، او په تېر شوو کالونو کښې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22010, 'Malachi 3:5', 'Malachi', 3, 5, '&nbsp;”نو زۀ به تاسو له د عدالت دپاره نزدې درشم. زر به زۀ د جادوګرو، زناکارو او چې په دروغو قسم خورى د هغوئ خلاف ګواهى ورکړم، د هغوئ خلاف چې د مزدورانو سره په مزدورۍ کښې ټګى کوى، څوک چې په کونډو او يتيمانانو ظلم کوى، او مسافر د اِنصاف نه محروموى خو زما نه نۀ يريږى،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22011, 'Malachi 3:6', 'Malachi', 3, 6, '&nbsp;”زۀ نۀ بدلېدونکے مالِک خُدائ يم. نو ځکه تاسو، اے د يعقوب اولاده، تباه نۀ شوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22012, 'Malachi 3:7', 'Malachi', 3, 7, '&nbsp;ستاسو د پلار نيکونو د وخت نه تاسو زما د احکامو نه اوړېدلې يئ او عمل مو پرې نۀ دے کړے. ما ته راوګرځئ، او زۀ به تاسو ته راوګرځم،“ مالِک خُدائ ربُ الافواج فرمائى. ”خو تاسو تپوس کوئ، مونږ څنګه راوګرځُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22013, 'Malachi 3:8', 'Malachi', 3, 8, '&nbsp;خو زۀ وايم چې، ولې يو سړے د خُدائ پاک نه غلا کولے شى څۀ؟ خو باوجود د دې تاسو زما نه غلا کوئ. خو بيا تاسو تپوس کوئ چې، مونږ تا نه څنګه غلا کوُو؟ خو زۀ دا وايم چې، تاسو په لسمه حِصه او نذرانو کښې زما نه غلا کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22014, 'Malachi 3:9', 'Malachi', 3, 9, '&nbsp;په تاسو او ستاسو په ټول قوم لعنت دے، ځکه چې تاسو ما نه غلا کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22015, 'Malachi 3:10', 'Malachi', 3, 10, '&nbsp;خپله ټوله لسمه حِصه زما ګودام ته راوړئ، چې زما په کور کښې غله دانه وى. په خپل دې کار سره ما وآزمايئ،“ مالِک خُدائ ربُ الافواج فرمائى، ”نو تاسو به ګورئ چې زۀ درته د آسمان نه د باران دروازې خلاصى کړم او په تاسو به دومره ډېر نعمتونه راوروم چې بيا به تاسو سره د دې دپاره د کېښودو ځائ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22016, 'Malachi 3:11', 'Malachi', 3, 11, '&nbsp;زۀ به ستاسو فصلونه د وبا او مُولخانو د تباه کولو نه وساتم، او ستاسو په پټو کښې به د انګورو بوټى، انګور د پخېدلو نه وړاندې نۀ غورزوى،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22017, 'Malachi 3:12', 'Malachi', 3, 12, '&nbsp;”بيا به ټول قومونه تاسو ته بختور وائى، ځکه چې تاسو به يو ښاد او آباد مُلک يئ،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22018, 'Malachi 3:13', 'Malachi', 3, 13, '&nbsp;مالِک خُدائ فرمائى چې، ”تاسو زما په حقله سپکې سپورې خبرې وکړې،“ ”خو اوس تاسو تپوس کوئ چې، مونږ ستا خلاف څۀ وئيلى دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22019, 'Malachi 3:14', 'Malachi', 3, 14, '&nbsp;تاسو ووئيل چې، د خُدائ پاک خِدمت کول بې‌فائدې دى. مونږ د هغۀ د حکمونو په منلو او د مالِک خُدائ ربُ الافواج په حضور کښې په خپلو ګناهونو په ماتم کولو څۀ حاصل کړل؟ نه، هيڅ نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22020, 'Malachi 3:15', 'Malachi', 3, 15, '&nbsp;نو اوس مونږ مغروره خلقو ته بختور وايو. يقيناً چې بدعمله خلق ترقى کوى، او تر دې چې هغوئ څوک چې د خُدائ پاک مقابله کوى سزا نۀ ګورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22021, 'Malachi 3:16', 'Malachi', 3, 16, '&nbsp;د دې نه وروستو، بيا کوم کسان چې د مالِک خُدائ نه يرېدل يو بل سره يې خبرې وکړې، او مالِک خُدائ ورته غوږ شو او هغه يې واورېدلې. د هغۀ په حضور کښې يو يادګارى طومار ليکلے شوے وو د هغوئ د نومونو په حقله څوک چې د مالِک خُدائ نه يرېدل او د هغۀ د نوم عزت يې کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22022, 'Malachi 3:17', 'Malachi', 3, 17, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى، ”هغوئ به زما وى. په هغه ورځ کله چې زۀ هغوئ خپل خاص ملکيت جوړوم، زۀ به هغوئ سره همدردى وکړم، لکه څنګه چې يو کس د خپل هغه زوئ سره همدردى کوى څوک چې د هغۀ خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22023, 'Malachi 3:18', 'Malachi', 3, 18, '&nbsp;او بيا به تاسو د صادقانو او بدعملو په اَنجام کښې فرق وګورئ، او هم به تاسو د هغوئ اَنجام کښې فرق وګورئ څوک چې د خُدائ پاک خِدمت کوى او څوک يې چې نۀ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22024, 'Malachi 4:1', 'Malachi', 4, 1, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى، ”يقيناً چې هغه ورځ راروانه ده، او هغه به لکه د بټۍ په شان بليږى. په هغه ورځ به ټول مغروره او بدعمله خلق لکه د بوسو په شان وسوزى. د هغوئ جرړې او ټولې څانګې به وسوزى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22025, 'Malachi 4:2', 'Malachi', 4, 2, '&nbsp;خو ستاسو دپاره څوک چې زما د نوم عزت کوى، صداقت او شفا به لکه د نمر په تاسو وځليږى. او تاسو به بهر لاړ شئ او د هغه سخو په شان به ټوپونه وهئ چې د غوجل نه آزاد شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22026, 'Malachi 4:3', 'Malachi', 4, 3, '&nbsp;په هغه ورځ کله چې زۀ دا کار وکړم نو تاسو به بدعمله لکه د ايرو په شان د پښو لاندې کړئ،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22027, 'Malachi 4:4', 'Malachi', 4, 4, '&nbsp;”زما د خِدمت کوونکى موسىٰ شريعت او هغه احکام، او فرمانونه چې ما هغۀ ته په سينا غر باندې د ټولو بنى اِسرائيلو دپاره ورکړى وُو ياد ساتئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22028, 'Malachi 4:5', 'Malachi', 4, 5, '&nbsp;ګورئ، زۀ به تاسو ته الياس پېغمبر د مالِک خُدائ د قيامت د هغه لوئې او هيبتناکې ورځې د راتلو نه مخکښې درولېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22029, 'Malachi 4:6', 'Malachi', 4, 6, '&nbsp;هغه به د پلارانو زړونه خپلو بچو ته مائل کړى، مالِک خُدائ ربُ الافواج فرمائى، او د بچو زړونه به خپلو پلارانو طرف ته مائل کړى، هسې نه چې زۀ راشم او ستاسو په مُلک د ورانولو فېصله نازله کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22030, 'Matthew 1:1', 'Matthew', 1, 1, '&nbsp;د عيسىٰ مسيح نسب‌نامه، نسل د داؤد، نسل د اِبراهيم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22031, 'Matthew 1:2', 'Matthew', 1, 2, '&nbsp;اِبراهيم د اِسحاق پلار وو، اِسحاق د يعقوب، يعقوب د يهوداه او د هغۀ د وروڼو پلار وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22032, 'Matthew 1:3', 'Matthew', 1, 3, '&nbsp;او يهوداه د فارص او زارح پلار وو، د دوئ مور تامار وه. فارص نه حصرون او حصرون نه رام پېدا شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22033, 'Matthew 1:4', 'Matthew', 1, 4, '&nbsp;د رام نه عمى‌نداب پېدا شو. د عمى‌نداب نه نحشون پېدا شو او د نحشون نه سلمون،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22034, 'Matthew 1:5', 'Matthew', 1, 5, '&nbsp;د سلمون نه بوعز، د دۀ مور راحب وه، د بوعز نه عوبيد پېدا شو، د دۀ مور روت وه. د عوبيد نه يَسى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22035, 'Matthew 1:6', 'Matthew', 1, 6, '&nbsp;او د يَسى نه داؤد بادشاه پېدا شو. داؤد د سليمان پلار وو، د هغۀ مور اول د اورِياه ښځه وه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22036, 'Matthew 1:7', 'Matthew', 1, 7, '&nbsp;د سليمان زوئ رحُبعام وو، د رحُبعام زوئ ابياه، د ابياه زوئ آسا.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22037, 'Matthew 1:8', 'Matthew', 1, 8, '&nbsp;د آسا زوئ يهوسفط، د يهوسفط زوئ يورام او د يورام زوئ عُزياه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22038, 'Matthew 1:9', 'Matthew', 1, 9, '&nbsp;او د عُزياه زوئ يوتام او د يوتام زوئ احاز، د احاز زوئ حزقياه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22039, 'Matthew 1:10', 'Matthew', 1, 10, '&nbsp;د حزقياه زوئ منسى، د منسى زوئ امون، د امون زوئ يوسياه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22040, 'Matthew 1:11', 'Matthew', 1, 11, '&nbsp;د يوسياه زوئ يکونياه، او د هغۀ وروڼه په هغه زمانه کښې پېدا شول چې بابل ته جلاوطن کړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22041, 'Matthew 1:12', 'Matthew', 1, 12, '&nbsp;د جلاوطنۍ او بابل ته د دوئ د بوتللو نه پس د يکونياه نه شلتى‌اېل پېدا شو او شلتى‌اېل د زرُبابل پلار وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22042, 'Matthew 1:13', 'Matthew', 1, 13, '&nbsp;زرُبابل د ابيهود، او ابيهود د اِلياقيم او اِلياقيم د عازور پلار وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22043, 'Matthew 1:14', 'Matthew', 1, 14, '&nbsp;او د عازور نه صدوق پېدا شو، صدوق د اخيم پلار وو، اخيم د اليهود،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22044, 'Matthew 1:15', 'Matthew', 1, 15, '&nbsp;اليهود د اِلى‌عزر، اِلى‌عزر د متان، متان د يعقوب،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22045, 'Matthew 1:16', 'Matthew', 1, 16, '&nbsp;او يعقوب د يوسف پلار وو. يوسف د مريم خاوند وو چې عيسىٰ ترې پېدا شو څوک چې مسيح بللے کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22046, 'Matthew 1:17', 'Matthew', 1, 17, '&nbsp;د اِبراهيم نه تر داؤد پورې ټولې څوارلس پيړۍ دى، او د داؤد نه بابل ته د جلاوطنۍ پورې څوارلس پيړۍ، او د جلاوطنۍ نه تر مسيح پورې څوارلس پيړۍ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22047, 'Matthew 1:18', 'Matthew', 1, 18, '&nbsp;نو د عيسىٰ مسيح د پېدايښت قيصه داسې ده چې هرکله چې د هغۀ مور مريم يوسف ته کوژدن شوه نو د وادۀ نه وړاندې دا پته ولګېده چې د هغې اُميدوارى د روحُ القُدس نه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22048, 'Matthew 1:19', 'Matthew', 1, 19, '&nbsp;يوسف د هغې چنغول يو نېک سړے وو، نو هغۀ د هغې د بدنامۍ نه د بچ کولو دپاره په پړده کښې د کوژدن ماتولو اراده وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22049, 'Matthew 1:20', 'Matthew', 1, 20, '&nbsp;هغۀ دا اراده کړې وه چې په دې کښې د مالِک خُدائ يوه فرښته په خوب کښې ورته راغله او وې فرمائيل چې، ”اے د داؤد زويه يوسفه، د مريم سره د وادۀ کولو نه مۀ يرېږه ځکه چې د هغې اُميدوارى د روحُ القُدس په قدرت ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22050, 'Matthew 1:21', 'Matthew', 1, 21, '&nbsp;د هغې به زوئ وشى او تۀ پرې عيسىٰ نوم کېږده، ولې چې هغه به خپل اُمت د ګناهونو نه خلاصوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22051, 'Matthew 1:22', 'Matthew', 1, 22, '&nbsp;دا هر څۀ ځکه وشول چې مالِک خُدائ د پېغمبر په وسيله څۀ فرمائيلى وُو هغه پوره شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22052, 'Matthew 1:23', 'Matthew', 1, 23, '&nbsp;”ګوره، يوه پېغله به اُميدواره شى او زوئ به يې وشى او د هغۀ نوم به عمانو‌ايل کېږدى، چې مطلب يې دے، خُدائ پاک زمونږ مل دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22053, 'Matthew 1:24', 'Matthew', 1, 24, '&nbsp;هرکله چې يوسف د خوبه بېدار شو نو د مالِک خُدائ د فرښتې حکم يې ومنلو او مريم سره يې وادۀ وکړو او کور ته يې راوسته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22054, 'Matthew 1:25', 'Matthew', 1, 25, '&nbsp;نو بيا هغه تر هغه وخته پورې د هغې سره مِلاو نۀ شو ترڅو چې د هغې زوئ پېدا شوے نۀ وو. نو هغۀ پرې عيسىٰ نوم کېښودو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22055, 'Matthew 2:1', 'Matthew', 2, 1, '&nbsp;د هيروديس بادشاه په ورځو کښې د يهوديه په بيت‌لحم کښې عيسىٰ پېدا شو. د هغۀ د پېدايښت نه پس يروشلم ته د نمرخاتۀ طرف نه د ستورو عِلم لرونکى راغلل', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22056, 'Matthew 2:2', 'Matthew', 2, 2, '&nbsp;او وئيل يې چې، ”هغه د يهوديانو بادشاه کېدونکے ماشوم چې پېدا شوے دے چرته دے؟ ځکه چې مونږ د نمرخاتۀ نه د هغۀ ستورے په راختو ليدلے دے او د هغۀ عبادت کولو له راغلى يُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22057, 'Matthew 2:3', 'Matthew', 2, 3, '&nbsp;هيروديس بادشاه او د يروشلم ټول خلق په دې اورېدو سره پرېشانه شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22058, 'Matthew 2:4', 'Matthew', 2, 4, '&nbsp;هغۀ د يهوديانو ټول مشران اِمامان او د شرعې عالمان راوبلل او د هغوئ نه يې دا تپوس وکړو چې، ”مسيح به چرته پېدا کيږى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22059, 'Matthew 2:5', 'Matthew', 2, 5, '&nbsp;هغوئ ووئيل چې، ”د يهوديه په بيت‌لحم کښې.“ او هغوئ د هغې پېشګويۍ حواله ورکړه چې په کښې د نبى په وسيله ليکلے شوى دى چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22060, 'Matthew 2:6', 'Matthew', 2, 6, '&nbsp;”اے د يهوداه د زمکې بيت‌لحم ښاريې. تۀ د يهوداه په لويو ښارونو کښې هيڅکله هم ورکوټې نۀ يې، ځکه چې ستا نه به هغه سردار راوځى چې زما د خلقو بنى اِسرائيلو شپون به وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22061, 'Matthew 2:7', 'Matthew', 2, 7, '&nbsp;هيروديس بيا د ستورو عِلم لرونکى په پړده کښې راوبلل او د ستورى د راختو وخت يې ترې معلوم کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22062, 'Matthew 2:8', 'Matthew', 2, 8, '&nbsp;هغۀ بيا دوئ بيت‌لحم ته ولېږل او ورته يې ووئيل چې، ”لاړ شئ او د هغه ماشوم په حقله پوره پوره تلاش وکړئ، او چې يې بيامومئ نو ما خبر کړئ چې زۀ هم ورشم او ورته سجده وکړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22063, 'Matthew 2:9', 'Matthew', 2, 9, '&nbsp;د بادشاه په حُکم هغوئ روان شول او هغه ستورے چې دوئ په راختو ليدلے وو د دوئ په وړاندې روان وو او آخر په هغه ځائ ودرېدو چرته چې ماشوم پروت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
