(22087, 'Matthew 3:10', 'Matthew', 3, 10, '&nbsp;اوس هم د ونو جرړو ته تبر نيولے شوے دے او هره هغه ونه چې ښۀ مېوه نۀ نيسى هغه به پرې کړے شى او د اور لمبو ته به واچولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22088, 'Matthew 3:11', 'Matthew', 3, 11, '&nbsp;زۀ تاسو له د توبې دپاره په اوبو بپتسمه درکوم خو څوک چې به زما نه وروستو راځى هغه زما نه ډېر زورَور دے. زۀ د هغۀ د څپلو پورته کولو جوګه هم نۀ يم. هغه به تاسو له په روحُ القُدس او په اور بپتسمه درکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22089, 'Matthew 3:12', 'Matthew', 3, 12, '&nbsp;ښاخۍ د هغۀ په لاس کښې ده. هغه به خپل درمند په ښۀ شان پاکوى او غنم به په خپله خمبه کښې جمع کوى، خو بوس به په هغه اور کښې سوزوى چې هيڅکله نۀ مرى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22090, 'Matthew 3:13', 'Matthew', 3, 13, '&nbsp;بيا عيسىٰ د ګليل نه د اُردن د سيند خوا ته راغلو چې د يحيىٰ نه بپتسمه واخلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22091, 'Matthew 3:14', 'Matthew', 3, 14, '&nbsp;خو يحيىٰ هغه منع کړو او ورته يې وفرمائيل چې، ”ما ته په کار دى چې زۀ ستا نه بپتسمه واخلم او تۀ ما له راغلې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22092, 'Matthew 3:15', 'Matthew', 3, 15, '&nbsp;عيسىٰ ورته وفرمائيل چې، ”په دې وخت هم داسې کول په کار دى ځکه چې مونږ له دغه شان د خُدائ پاک صداقت پوره کول مناسب دى.“ او بيا يحيىٰ دا ومنله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22093, 'Matthew 3:16', 'Matthew', 3, 16, '&nbsp;د بپتسمې نه پس عيسىٰ د اوبو نه سمدستى راوختلو او په هغه وخت ورته آسمان کولاو شو او د خُدائ پاک روح يې وليدو چې د کونترې په شکل په هغۀ راکوزېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22094, 'Matthew 3:17', 'Matthew', 3, 17, '&nbsp;او د آسمان نه يو آواز راغلو چې، ”دا زما خوږ زوئ دے چې زۀ ترې راضى يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22095, 'Matthew 4:1', 'Matthew', 4, 1, '&nbsp;روحُ القُدس هغه وخت عيسىٰ بيابان ته بوتلو چې د اِبليس په لمسون کښې وآزمائيلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22096, 'Matthew 4:2', 'Matthew', 4, 2, '&nbsp;هغۀ څلوېښت ورځې او څلوېښت شپې روژه ونيوله او په آخر کښې هغه نار نهور شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22097, 'Matthew 4:3', 'Matthew', 4, 3, '&nbsp;بيا اِبليس ورغلو او ورته يې ووئيل، ”کۀ تۀ د خُدائ پاک زوئ يې نو دې کاڼو ته ووايه چې روټۍ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22098, 'Matthew 4:4', 'Matthew', 4, 4, '&nbsp;عيسىٰ جواب ورکړو، ”صحيفې وائى چې، بنى آدم تش په روټۍ نۀ پائى خو هغه په هره هغه خبره پائى چې د خُدائ پاک د خولې نه راوځى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22099, 'Matthew 4:5', 'Matthew', 4, 5, '&nbsp;بيا اِبليس هغه مقدس ښار ته بوتلو او د خُدائ د کور په مناره يې ودرولو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22100, 'Matthew 4:6', 'Matthew', 4, 6, '&nbsp;او ورته يې ووئيل چې، ”کۀ تۀ د خُدائ پاک زوئ يې نو خپل ځان دلته نه ښکته وغورزوه، ځکه چې صحيفې وائى چې، هغه به ستا په حقله خپلو فرښتو له حُکم ورکړى، او هغوئ به تا په خپلو لاسونو کښې پورته کړى هسې نه چې په کاڼى تيندک وخورى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');